/// <summary>
/// The <c>AVAWHSProcessGuideScanInitialLicensePlateIdPageBuilderCls_Extension</c> represents a extension of <c>WHSProcessGuideScanInitialLicensePlateIdPageBuilder</c> class.
/// </summary>
/// <remarks>
/// AVA_8065_10657_MDEAutoPackContainerType
/// </remarks>
[
    ExtensionOf(classStr(WHSProcessGuideScanInitialLicensePlateIdPageBuilder))
]
final class AVAWHSProcessGuideScanInitialLicensePlateIdPageBuilderCls_Extension
{
}

Method.Source:
/// <summary>
/// Extension methode for addDataControls
/// </summary>
/// <param name = "_page">
/// <c>ProcessGuidePage</c> class
/// </param>
protected void addDataControls(ProcessGuidePage _page)
{
    next addDataControls(_page);

    WhsrfPassthrough avaPass = controller.parmSessionState().parmPass();

    if (avaPass.exists(ProcessGuideDataTypeNames::ContainerId) && avaPass.avaParmContainerType())
    {
        if (!WHSContainerTable::findByContainerId(avaPass.lookup(ProcessGuideDataTypeNames::ContainerId)))
        {
            _page.avaUpdateTextBox(
                ProcessGuideDataTypeNames::LicensePlateId,
                "@WAX1198",
                extendedTypeNum(WHSLicensePlateId),
                true,
                avaPass.parmLicensePlateId());

            this.avaAddContainerTypeDataControls(_page);
        }
        else 
        {
            this.avaAddContainerTypeDataControls(_page, true);
        }
    }
    else 
    {
        _page.avaUpdateTextBox(
            ProcessGuideDataTypeNames::LicensePlateId,
            "@WAX1198",
            extendedTypeNum(WHSLicensePlateId),
            true,
            avaPass.parmLicensePlateId());

        this.avaAddContainerTypeDataControls(_page);
    }

}

private void avaAddContainerTypeDataControls(ProcessGuidePage _page, boolean _emptyValue = false)
{
    WhsrfPassthrough    avaPass;
    boolean             avaAddEmpty;
    boolean             avaEnabled;
    str                 avaDefaultContainerTypeCode;
    UserId              avaUserId;
    WHSWorkUser         avaWHSWorkUser;
    WHSWorker           avaWHSWorker;

    avaPass                        = controller.parmSessionState().parmPass();
    avaAddEmpty                    = true;
    avaEnabled                     = true;

    if (_emptyValue)
    {
        _page.addComboBox(ProcessGuideDataTypeNames::AVAContainerType,
            "@WAX1440",
            extendedTypeNum(WHSDefaultContainerTypeCode),
            ProcessGuideDelimiterHelper::getDelimitedList(tableNum(WHSContainerType), fieldNum(WHSContainerType, ContainerTypeCode), ProcessGuideDataTypeNames::ListSeparator, avaAddEmpty),
            avaEnabled,
            avaDefaultContainerTypeCode);
        return;
    }
    else
    {
        if (avaPass.parmLicensePlateId())
        {
            avaDefaultContainerTypeCode = WHSLicensePlate::find(avaPass.parmLicensePlateId()).ContainerTypeCode;

            if (!avaDefaultContainerTypeCode)
            {
                avaDefaultContainerTypeCode = WHSRFDefaultData::getDefaultValue(avaPass.lookupStr(ProcessGuideDataTypeNames::MenuItem),
                                                                                WHSDefaultDataField::ContainerType,
                                                                                avaPass.lookupStr(ProcessGuideDataTypeNames::UserId),
                                                                                avaPass.lookupStr(ProcessGuideDataTypeNames::InventLocationId),
                                                                                avaPass.lookupStr(ProcessGuideDataTypeNames::WMSLocationId));
            }

            if (!avaDefaultContainerTypeCode)
            {
                avaUserId                   = avaPass.lookupStr(ProcessGuideDataTypeNames::UserId);
                avaWHSWorkUser              = WHSWorkUser::find(avaUserId);
                avaWHSWorker                = WHSWorker::find(avaWHSWorkUser.Worker);
                avaDefaultContainerTypeCode = WHSPackProfile::find(avaWHSWorker.PackProfileId).DefaultContainerType;
            }
        }
    }                                         

    _page.addComboBox(ProcessGuideDataTypeNames::AVAContainerType,
            "@WAX1440",
            extendedTypeNum(WHSDefaultContainerTypeCode),
            ProcessGuideDelimiterHelper::getDelimitedList(tableNum(WHSContainerType), fieldNum(WHSContainerType, ContainerTypeCode), ProcessGuideDataTypeNames::ListSeparator, avaAddEmpty),
            avaEnabled,
            avaDefaultContainerTypeCode);
}
